from commun import article_seo, M

FR = '/surcharge-progressive.html'
DATE = '2026-11-18'
C = 'surcharge'

SOURCES = [
 'Plotkin D, Coleman M, Van Every D et al. “Progressive overload without progressing load? The effects of load or repetition progression on muscular adaptations”. <i>PeerJ</i>, 2022, 10:e14142.',
 'American College of Sports Medicine. “Progression models in resistance training for healthy adults”. <i>Medicine &amp; Science in Sports &amp; Exercise</i>, 2009, 41(3):687-708.',
 'Schoenfeld BJ, Grgic J, Ogborn D, Krieger JW. “Strength and hypertrophy adaptations between low- vs. high-load resistance training: a systematic review and meta-analysis”. <i>Journal of Strength and Conditioning Research</i>, 2017, 31(12):3508-3523.',
 'Schoenfeld BJ, Ogborn D, Krieger JW. “Dose-response relationship between weekly resistance training volume and increases in muscle mass: a systematic review and meta-analysis”. <i>Journal of Sports Sciences</i>, 2017, 35(11):1073-1082.',
]

EN = dict(publie=DATE,
 title='Progressive overload: how to keep making gains',
 desc='Progressive overload: adding load, reps or sets to keep progressing in strength training. How to do it, and how fast to increase.',
 court='Progressive overload', surtitre='Strength training',
 h1='Progressive overload: how to keep progressing in the gym',
 chapeau='A muscle adapts to what you ask of it, then stops adapting if you always ask for the same thing. Progressive overload simply means asking for a little more, regularly and measurably. The principle fits in one sentence; applying it mostly takes knowing what you did last time.',
 situation='You have been benching the same 60 kg for two months, and you can no longer remember whether you did 8 or 10 reps last week. <strong>With Basal:</strong> during a session, each exercise shows your last performance, for example “60 kg × 10, 9, 8”, and the exercise page tracks your top weight, estimated 1RM and records.',
 bref='Progressive overload means gradually increasing the effort: more load, more reps or more sets. Adding reps gives results comparable to adding load. The simplest rule: once you go past the top of your rep range on every set, raise the load by about 2 to 5%.',
 sections=[
  ('definition', 'Progressive overload: the definition', '<p>Progressive overload is the principle that training has to become slightly more demanding over time to keep producing progress. The body responds to a stress by adapting to it; once adapted, the same stress is no longer enough. It is not one method among others: it is what every strength training method has in common.</p>'),
  ('levers', 'The levers of progressive overload: load, reps, sets', '<p>You can make a session more demanding in several ways:</p><ul><li><strong>load</strong>: lifting heavier for the same number of reps;</li><li><strong>reps</strong>: doing more reps with the same load;</li><li><strong>sets</strong>: adding a set, and so volume (<a href="@series">sets per muscle</a>);</li><li><strong>execution</strong>: same load, fuller range of motion or better-controlled tempo.</li></ul><p>A 2022 study compared two groups over eight weeks: one increased the load, the other the reps. Muscle gains were comparable, with a slight strength advantage for the group that raised the load [1]. Both routes work.</p>'),
  ('rate', 'Progressive overload: how fast to increase', '<p>The American College of Sports Medicine recommends increasing the load by about <strong>2 to 10%</strong> once you can do one or two reps more than planned in two consecutive sessions [2]. In practice, 2.5 kg is often already a lot on upper-body lifts; a beginner progresses almost every session, someone with several years of training over weeks.</p><p>A simple method is <strong>double progression</strong>: pick a range, for example 8 to 12 reps. Increase the reps session after session; when every set reaches 12, add load and work back up from 8.</p>'),
  ('heavy-light', 'Heavy or light loads: what really matters', '<p>For muscle size, a meta-analysis found no clear difference between heavy sets and lighter sets, as long as they are taken close to failure; for maximal strength, heavy loads keep the edge [3]. What matters is that the effort increases, not how it increases.</p><p>Weekly volume also plays a part: more sets per muscle give more growth on average, up to a point [4].</p>'),
  ('stall', 'When progress stops', '<p>Sooner or later, the load stops going up. Before changing programme, check three things: sleep, calories and protein. In a <a href="@deficit">calorie deficit</a>, progressing gets harder, and holding your loads is already a good result (<a href="@seche">cutting</a>). If everything is in place, switching lever often helps: moving from load to reps, or adding a set.</p>'),
  ('basal', 'Progressive overload in Basal: knowing what you did last time', '<p>During a session, each exercise shows your <strong>last performance</strong>, with its date and sets, for example “60 kg × 10, 9, 8”. That is the information you need in the gym to decide whether to raise the load or the reps. Warm-up sets are not counted, so a light set before the real weight does not skew anything.</p><p>Each exercise page tracks top weight, <a href="@1rm">estimated 1RM</a> (Epley formula: 80 kg × 8 reps gives about 101 kg), volume and reps, and marks your records. Volume is deliberately left out of records: making it a record would push you to lengthen sessions rather than progress. The volume each muscle group gets is counted in Premium.</p>'),
  ('unknown', 'What we don’t know', '<p>There is no ideal rate of progress that holds for everyone: it depends on training age, the exercise, recovery and diet. Studies compare groups over a few weeks, rarely over several years. The estimated 1RM is an estimate: the formula becomes less reliable beyond about ten reps.</p>'),
 ],
 appel=('Your last session in front of you, for every exercise', 'Basal shows what you did last time, tracks your loads and records, and puts them next to your meals and your weight. Tracking is free, ad-free and needs no account.'),
 sources=SOURCES,
 plus=[('series', None, 'Sets per muscle', 'How many sets a week to progress.'),
       ('1rm', M['en']['calc'], 'One-rep max calculator', 'Your estimated maximum, without testing it.'),
       ('nutrition-musculation', None, 'Nutrition for strength training', 'Are you eating enough to progress?')])

ES = dict(publie=DATE,
 title='Sobrecarga progresiva: cómo seguir progresando en el gym',
 desc='Sobrecarga progresiva: añadir carga, repeticiones o series para seguir progresando en el entrenamiento de fuerza. Cómo hacerlo y a qué ritmo.',
 court='Sobrecarga progresiva', surtitre='Entrenamiento de fuerza',
 h1='Sobrecarga progresiva: cómo seguir progresando en el entrenamiento de fuerza',
 chapeau='Un músculo se adapta a lo que le pides y deja de adaptarse si siempre le pides lo mismo. La sobrecarga progresiva consiste simplemente en pedir un poco más, de forma regular y medible. El principio cabe en una frase; aplicarlo exige sobre todo saber qué hiciste la última vez.',
 situation='Llevas dos meses haciendo press de banca con los mismos 60 kg y ya no recuerdas si la semana pasada hiciste 8 o 10 repeticiones. <strong>Con Basal:</strong> durante la sesión, cada ejercicio muestra tu último rendimiento, por ejemplo «60 kg × 10, 9, 8», y la página del ejercicio sigue tu carga máxima, tu 1RM estimado y tus récords.',
 bref='La sobrecarga progresiva consiste en aumentar poco a poco el esfuerzo: más carga, más repeticiones o más series. Añadir repeticiones da resultados comparables a añadir carga. La regla más sencilla: cuando superas el máximo de tu rango de repeticiones en todas las series, sube la carga un 2 a 5 % aproximadamente.',
 sections=[
  ('definicion', 'Sobrecarga progresiva: la definición', '<p>La sobrecarga progresiva es el principio según el cual un entrenamiento debe volverse algo más exigente con el tiempo para seguir produciendo progresos. El cuerpo responde a un estrés adaptándose; una vez adaptado, el mismo estrés ya no basta. No es un método entre otros: es lo que todos los métodos de fuerza tienen en común.</p>'),
  ('palancas', 'Las palancas de la sobrecarga progresiva: carga, repeticiones, series', '<p>Se puede hacer una sesión más exigente de varias formas:</p><ul><li><strong>la carga</strong>: levantar más peso con el mismo número de repeticiones;</li><li><strong>las repeticiones</strong>: hacer más repeticiones con la misma carga;</li><li><strong>las series</strong>: añadir una serie, es decir, volumen (<a href="@series">series por músculo</a>);</li><li><strong>la ejecución</strong>: misma carga, recorrido más completo o tempo mejor controlado.</li></ul><p>Un estudio de 2022 comparó dos grupos durante ocho semanas: uno aumentaba la carga y el otro las repeticiones. Las ganancias de masa muscular fueron comparables, con una ligera ventaja de fuerza para el grupo que subía la carga [1]. Los dos caminos funcionan.</p>'),
  ('ritmo', 'Sobrecarga progresiva: a qué ritmo aumentar', '<p>Las recomendaciones del American College of Sports Medicine proponen aumentar la carga un <strong>2 a 10 %</strong> aproximadamente cuando puedes hacer una o dos repeticiones más de lo previsto en dos sesiones seguidas [2]. En la práctica, en los ejercicios de tren superior, 2,5 kg ya suele ser mucho; un principiante progresa casi en cada sesión, alguien con años de entrenamiento en semanas.</p><p>Un método sencillo es la <strong>doble progresión</strong>: elige un rango, por ejemplo de 8 a 12 repeticiones. Sube las repeticiones sesión tras sesión; cuando todas las series llegan a 12, añade carga y vuelve a empezar desde 8.</p>'),
  ('pesado-ligero', 'Cargas pesadas o ligeras: lo que cuenta de verdad', '<p>Para la masa muscular, un metaanálisis no encontró una diferencia clara entre series pesadas y series más ligeras, siempre que se lleven cerca del fallo; para la fuerza máxima, las cargas pesadas mantienen la ventaja [3]. Lo que cuenta es que el esfuerzo aumente, no la forma en que aumenta.</p><p>El volumen semanal también influye: más series por músculo dan de media más crecimiento, hasta cierto punto [4].</p>'),
  ('estancamiento', 'Cuando el progreso se detiene', '<p>Tarde o temprano, la carga deja de subir. Antes de cambiar de programa, revisa tres puntos: el sueño, las calorías y las proteínas. En <a href="@deficit">déficit calórico</a> progresar es más difícil, y mantener las cargas ya es un buen resultado (<a href="@seche">definición muscular</a>). Si todo está en orden, cambiar de palanca suele ayudar: pasar de la carga a las repeticiones, o añadir una serie.</p>'),
  ('basal', 'Sobrecarga progresiva en Basal: saber qué hiciste la última vez', '<p>Durante una sesión, cada ejercicio muestra tu <strong>último rendimiento</strong>, con su fecha y sus series, por ejemplo «60 kg × 10, 9, 8». Es la información que necesitas en el gimnasio para decidir si subes la carga o las repeticiones. Las series de calentamiento no se cuentan, para que una serie ligera antes de la carga real no falsee nada.</p><p>La página de cada ejercicio sigue la carga máxima, el <a href="@1rm">1RM estimado</a> (fórmula de Epley: 80 kg × 8 repeticiones dan unos 101 kg), el volumen y las repeticiones, y marca tus récords. El volumen queda fuera de los récords a propósito: convertirlo en récord empujaría a alargar las sesiones en lugar de progresar. El volumen que recibe cada grupo muscular se cuenta en Premium.</p>'),
  ('desconocido', 'Lo que no sabemos', '<p>No existe un ritmo de progreso ideal válido para todo el mundo: depende de la experiencia, del ejercicio, de la recuperación y de la alimentación. Los estudios comparan grupos durante unas semanas, rara vez durante años. El 1RM estimado es una estimación: la fórmula pierde fiabilidad por encima de unas diez repeticiones.</p>'),
 ],
 appel=('Tu última sesión a la vista, en cada ejercicio', 'Basal muestra lo que hiciste la última vez, sigue tus cargas y tus récords, y los pone frente a tus comidas y tu peso. El seguimiento es gratuito, sin publicidad y sin cuenta.'),
 sources=SOURCES,
 plus=[('series', None, 'Series por músculo', 'Cuántas series por semana para progresar.'),
       ('1rm', M['es']['calc'], 'Calculadora de 1RM', 'Tu carga máxima estimada, sin probarla.'),
       ('nutrition-musculation', None, 'Nutrición y fuerza', '¿Comes lo suficiente para progresar?')])

DE = dict(publie=DATE,
 title='Progressive Überlastung: so machst du weiter Fortschritte',
 desc='Progressive Überlastung: mehr Gewicht, Wiederholungen oder Sätze, um im Krafttraining weiter Fortschritte zu machen. Wie es geht und in welchem Tempo.',
 court='Progressive Überlastung', surtitre='Krafttraining',
 h1='Progressive Überlastung: so machst du im Krafttraining weiter Fortschritte',
 chapeau='Ein Muskel passt sich an das an, was du von ihm verlangst, und hört damit auf, wenn du immer dasselbe verlangst. Progressive Überlastung heißt einfach, regelmäßig und messbar etwas mehr zu verlangen. Das Prinzip passt in einen Satz; um es umzusetzen, musst du vor allem wissen, was du beim letzten Mal gemacht hast.',
 situation='Du drückst seit zwei Monaten dieselben 60 kg auf der Bank und weißt nicht mehr, ob es letzte Woche 8 oder 10 Wiederholungen waren. <strong>Mit Basal:</strong> Während der Einheit zeigt jede Übung deine letzte Leistung, zum Beispiel „60 kg × 10, 9, 8“, und die Seite der Übung verfolgt dein Höchstgewicht, dein geschätztes 1RM und deine Rekorde.',
 bref='Progressive Überlastung heißt, die Belastung nach und nach zu steigern: mehr Gewicht, mehr Wiederholungen oder mehr Sätze. Mehr Wiederholungen bringen ähnliche Ergebnisse wie mehr Gewicht. Die einfachste Regel: Wenn du in allen Sätzen über das obere Ende deines Wiederholungsbereichs kommst, erhöhe das Gewicht um etwa 2 bis 5 %.',
 sections=[
  ('definition', 'Progressive Überlastung: die Definition', '<p>Progressive Überlastung ist das Prinzip, dass ein Training mit der Zeit etwas anspruchsvoller werden muss, damit es weiter Fortschritte bringt. Der Körper reagiert auf einen Reiz, indem er sich anpasst; ist er angepasst, reicht derselbe Reiz nicht mehr. Das ist keine Methode unter vielen: Es ist das, was alle Methoden des Krafttrainings gemeinsam haben.</p>'),
  ('hebel', 'Die Hebel der progressiven Überlastung: Gewicht, Wiederholungen, Sätze', '<p>Eine Einheit lässt sich auf mehrere Arten anspruchsvoller machen:</p><ul><li><strong>das Gewicht</strong>: schwerer heben bei gleicher Wiederholungszahl;</li><li><strong>die Wiederholungen</strong>: mehr Wiederholungen mit demselben Gewicht;</li><li><strong>die Sätze</strong>: einen Satz hinzufügen, also mehr Volumen (<a href="@series">Sätze pro Muskel</a>);</li><li><strong>die Ausführung</strong>: gleiches Gewicht, vollere Bewegungsamplitude oder besser kontrolliertes Tempo.</li></ul><p>Eine Studie von 2022 verglich zwei Gruppen über acht Wochen: Die eine steigerte das Gewicht, die andere die Wiederholungen. Der Muskelzuwachs war vergleichbar, mit einem leichten Kraftvorteil für die Gruppe, die das Gewicht erhöhte [1]. Beide Wege funktionieren.</p>'),
  ('tempo', 'Progressive Überlastung: in welchem Tempo steigern', '<p>Das American College of Sports Medicine empfiehlt, das Gewicht um etwa <strong>2 bis 10 %</strong> zu erhöhen, wenn du in zwei Einheiten hintereinander ein oder zwei Wiederholungen mehr schaffst als geplant [2]. In der Praxis sind 2,5 kg bei Oberkörperübungen oft schon viel; Einsteiger steigern sich fast in jeder Einheit, wer seit Jahren trainiert, über Wochen.</p><p>Eine einfache Methode ist die <strong>doppelte Progression</strong>: Wähle einen Bereich, etwa 8 bis 12 Wiederholungen. Steigere die Wiederholungen von Einheit zu Einheit; schaffst du in allen Sätzen 12, erhöhe das Gewicht und beginne wieder bei 8.</p>'),
  ('schwer-leicht', 'Schwere oder leichte Gewichte: was wirklich zählt', '<p>Für den Muskelaufbau fand eine Metaanalyse keinen deutlichen Unterschied zwischen schweren und leichteren Sätzen, solange sie nah ans Muskelversagen gehen; für die Maximalkraft behalten schwere Gewichte den Vorteil [3]. Entscheidend ist, dass die Belastung steigt, nicht auf welche Weise.</p><p>Auch das Wochenvolumen spielt mit: Mehr Sätze pro Muskel bringen im Mittel mehr Wachstum, bis zu einem gewissen Punkt [4].</p>'),
  ('stillstand', 'Wenn der Fortschritt stockt', '<p>Früher oder später steigt das Gewicht nicht mehr. Bevor du das Programm wechselst, prüfe drei Dinge: Schlaf, Kalorien und Eiweiß. Im <a href="@deficit">Kaloriendefizit</a> wird Fortschritt schwieriger, und die Gewichte zu halten ist schon ein gutes Ergebnis (<a href="@seche">Definitionsphase</a>). Stimmt alles, hilft es oft, den Hebel zu wechseln: vom Gewicht zu den Wiederholungen oder einen Satz mehr.</p>'),
  ('basal', 'Progressive Überlastung in Basal: wissen, was du beim letzten Mal gemacht hast', '<p>Während einer Einheit zeigt jede Übung deine <strong>letzte Leistung</strong> mit Datum und Sätzen, zum Beispiel „60 kg × 10, 9, 8“. Das ist die Information, die du im Studio brauchst, um zu entscheiden, ob du das Gewicht oder die Wiederholungen erhöhst. Aufwärmsätze werden nicht mitgezählt, damit ein leichter Satz vor dem eigentlichen Gewicht nichts verfälscht.</p><p>Die Seite jeder Übung verfolgt Höchstgewicht, <a href="@1rm">geschätztes 1RM</a> (Epley-Formel: 80 kg × 8 Wiederholungen ergeben etwa 101 kg), Volumen und Wiederholungen und markiert deine Rekorde. Das Volumen ist bewusst kein Rekord: Sonst würde es dazu verleiten, Einheiten zu verlängern statt Fortschritte zu machen. Das Volumen pro Muskelgruppe wird in Premium gezählt.</p>'),
  ('unbekannt', 'Was wir nicht wissen', '<p>Ein ideales Steigerungstempo für alle gibt es nicht: Es hängt von der Trainingserfahrung, der Übung, der Erholung und der Ernährung ab. Studien vergleichen Gruppen über wenige Wochen, selten über Jahre. Das geschätzte 1RM ist eine Schätzung: Über etwa zehn Wiederholungen hinaus wird die Formel ungenauer.</p>'),
 ],
 appel=('Deine letzte Einheit vor Augen, bei jeder Übung', 'Basal zeigt, was du beim letzten Mal gemacht hast, verfolgt deine Gewichte und Rekorde und stellt sie neben deine Mahlzeiten und dein Gewicht. Das Tracking ist kostenlos, werbefrei und braucht kein Konto.'),
 sources=SOURCES,
 plus=[('series', None, 'Sätze pro Muskel', 'Wie viele Sätze pro Woche für Fortschritte.'),
       ('1rm', M['de']['calc'], '1RM-Rechner', 'Dein geschätztes Maximum, ohne es zu testen.'),
       ('nutrition-musculation', None, 'Ernährung und Krafttraining', 'Isst du genug, um Fortschritte zu machen?')])

PAGES = {l: article_seo(l, C, a, f'{l}-{C}') for l, a in (('en', EN), ('es', ES), ('de', DE))}
